// Procurement reference codes (the public bidding ID).
//
// The code is generated by the backend only — the frontend never builds one.
// Three formats are live, because every code is the on-chain index of its
// blockchain trail and is never rewritten once issued:
//
//   P-2026-004           sequential (retired: guessable)
//   PRC-2026-7K4M-Q9XT   random, 8 characters + year (retired)
//   PC-7K4M-Q9XT-3HWD    current: 12 random characters, no year
//
// So lookups normalise what a person typed and accept any of them.

export const EXAMPLE_CODE = 'PC-7K4M-Q9XT-3HWD'

/** Canonical form of a typed or pasted reference: trimmed and upper-cased. */
export function normalizeProcurementCode(raw) {
  return String(raw ?? '').trim().toUpperCase()
}

const FORMATS = [
  /^P-\d{4}-\d{3,}$/,
  /^PRC-\d{4}-[0-9A-Z]{4}-[0-9A-Z]{4}$/,
  /^PC-[0-9A-Z]{4}-[0-9A-Z]{4}-[0-9A-Z]{4}$/,
]

/** Does `raw` look like a procurement code in any format ever issued? */
export function isProcurementCode(raw) {
  const code = normalizeProcurementCode(raw)
  return FORMATS.some((re) => re.test(code))
}
